/**
 * Text to render inside a click-to-view banner for a given provider.
 */

const MEDIA_EMBED_SELECTOR = '[data-s9e-mediaembed]';

/**
 * Replaces every oembed rendered by s9e/TextFormatter's MediaEmbed plugin
 * (identified by its `data-s9e-mediaembed` attribute) with an inert,
 * generic 16:9 click-to-view banner (no thumbnail, no attempt to match the
 * original embed's size — just the consent message and a button).
 *
 * The original iframe's `src` is moved to a `data-ctv-src` attribute, so the
 * browser never requests it — and therefore never sets any third-party
 * cookies — until the visitor explicitly consents to loading content from
 * that provider.
 *
 * This must run on the raw HTML string (before it is inserted into the live
 * DOM via `m.trust`), since by the time an element with a real `src` is
 * attached to the document, the browser will already have started loading it.
 */
export function transformEmbedsHtml(html, getBannerContent) {
  if (!html || !html.includes('data-s9e-mediaembed')) {
    return html || '';
  }
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const embeds = Array.from(doc.body.querySelectorAll(MEDIA_EMBED_SELECTOR));
  embeds.forEach(embed => {
    const site = embed.dataset.s9eMediaembed;
    // Most sites render as `<span data-s9e-mediaembed>` wrapping a nested
    // iframe, but "full width" sites (SoundCloud, Spotify, Mixcloud, CodePen,
    // and others configured with `width="100%"`) skip that wrapper entirely:
    // s9e puts the `data-s9e-mediaembed` attribute directly on the `<iframe>`
    // itself. Handle both shapes so none of those providers slip through.
    const iframe = embed.tagName === 'IFRAME' ? embed : embed.querySelector('iframe');

    // Only iframe-based embeds are supported; leave anything else untouched
    // rather than risk breaking it.
    if (!site || !iframe) {
      return;
    }
    const src = iframe.getAttribute('src');
    if (!src) {
      return;
    }
    iframe.setAttribute('data-ctv-src', src);
    iframe.removeAttribute('src');
    const {
      message,
      buttonLabel,
      sourceLinkLabel
    } = getBannerContent(site);
    const wrapper = doc.createElement('span');
    wrapper.className = 'ClickToView';
    wrapper.setAttribute('data-ctv-site', site);
    const embedContainer = doc.createElement('span');
    embedContainer.className = 'ClickToView-embed';
    embedContainer.hidden = true;

    // A generic 16:9 box, the same for every provider — no thumbnail, no
    // attempt to mirror the original embed's dimensions.
    const banner = doc.createElement('span');
    banner.className = 'ClickToView-banner';
    const content = doc.createElement('span');
    content.className = 'ClickToView-banner-content';
    const messageEl = doc.createElement('span');
    messageEl.className = 'ClickToView-banner-message';
    messageEl.textContent = message;
    const button = doc.createElement('button');
    button.type = 'button';
    button.className = 'Button Button--primary ClickToView-banner-button';
    button.setAttribute('data-ctv-action', 'reveal');
    button.textContent = buttonLabel;

    // A plain link to the URL that would otherwise have been embedded (the
    // iframe's own `src`), so visitors can open it directly without
    // granting consent — this is the actual resource s9e/TextFormatter
    // resolved, not necessarily the original page the author pasted.
    const sourceLink = doc.createElement('a');
    sourceLink.className = 'ClickToView-banner-link';
    sourceLink.href = src;
    sourceLink.target = '_blank';
    sourceLink.rel = 'nofollow noopener noreferrer';
    sourceLink.textContent = sourceLinkLabel;
    content.appendChild(messageEl);
    content.appendChild(button);
    content.appendChild(sourceLink);
    banner.appendChild(content);
    embed.replaceWith(wrapper);
    wrapper.appendChild(embedContainer);
    embedContainer.appendChild(embed);
    wrapper.appendChild(banner);
  });
  return doc.body.innerHTML;
}
flarum.reg.add('redundans-click-to-view', 'common/clickToView/transform', { transformEmbedsHtml: transformEmbedsHtml, });