import app from 'flarum/forum/app';
import { extend, override } from 'flarum/common/extend';
import Post from 'flarum/common/models/Post';
import CommentPost from 'flarum/forum/components/CommentPost';
import { transformEmbedsHtml } from '../common/clickToView/transform';
import { applyStoredConsent, bindClickToViewDelegation } from './clickToView/dom';
export { default as extend } from './extend';
app.initializers.add('redundans-click-to-view', () => {
  // Rewrite every post's rendered HTML so that s9e/TextFormatter media embeds
  // are replaced with an inert click-to-view banner before it ever reaches
  // the live DOM. This is what stops the browser from requesting the embed
  // (and any cookies that may come with it) before the visitor consents.
  override(Post.prototype, 'contentHtml', function (original) {
    const html = original();
    if (typeof html !== 'string') {
      return html;
    }
    return transformEmbedsHtml(html, site => ({
      // `extract: true` makes `trans()` return a plain string instead of an
      // array of Mithril children — without it, the array gets coerced to a
      // string (e.g. via `textContent =`) and joins its parts with commas,
      // producing text like "hosted by ,twitter,.".
      message: app.translator.trans('redundans-click-to-view.forum.click_to_view.message', {
        site
      }, true),
      buttonLabel: app.translator.trans('redundans-click-to-view.forum.click_to_view.button', {
        site
      }, true),
      sourceLinkLabel: app.translator.trans('redundans-click-to-view.forum.click_to_view.source_link', {
        site
      }, true)
    }));
  });

  // Reveal embeds for providers the visitor has already consented to, every
  // time a post is (re)rendered into the DOM.
  extend(CommentPost.prototype, ['oncreate', 'onupdate'], function () {
    applyStoredConsent(this.element);
  });
  bindClickToViewDelegation();
});